def max_length_subarray(arr, target_sum): 
  max_len = 0 
  for i in range(len(arr)): 
    curr_sum = 0 
    for j in range(i, len(arr)): 
      curr_sum += arr[j] 
      if curr_sum == target_sum: 
        max_len = max(max_len, j - i + 1) 
  return max_len

